def test_semantic_intent_readonly_respects_explicit_entity_override():
    assert _semantic_intent_decision_requires_readonly(
        {
            "decision": "mixed_answer_then_ask",
            "confidence": 0.9,
            "honored": False,
        }
    ) is False
    assert _semantic_intent_decision_requires_readonly(
        {
            "decision": "mixed_answer_then_ask",
            "confidence": 0.9,
            "honored": True,
        }
    ) is True


